INSERT INTO public.voice_training_questions (question, language, source_answer, approved_answer, topic, keywords, intent, sort_order, category) VALUES
('Who is the Managing Director of Kindred?', 'en', 'Approved fact sheet', 'Our Managing Director is Mrs. Adaeze Okonkwo-Bello. Kindred Microfinance Bank Limited is a licensed national microfinance bank, registration RC 1234567, founded in 2011. I don''t have ownership or shareholder details.', 'Managing Director', ARRAY['managing director','md','ceo','who runs','owner','founded','rc number','registration'], 'general', 100, 'Bank profile, Contact and Hours'),
('How many branches and customers does Kindred have?', 'en', 'Approved fact sheet', 'Kindred has 24 branches in 9 states, 180 Kindred Agent points and 6 ATMs, serving over 480,000 customers, including traders, SMEs, salary earners, cooperatives, students and farmers.', 'Bank network', ARRAY['how many branches','how many customers','agent points','atms','network','states'], 'general', 101, 'Bank profile, Contact and Hours'),
('What is Kindred''s mission and values?', 'en', 'Approved fact sheet', 'Our mission is to make everyday banking simple, safe and fair for people the big banks overlook. Our values are Trust, Simplicity, Fairness and Community.', 'Mission and values', ARRAY['mission','values','vision','tagline'], 'general', 102, 'Bank profile, Contact and Hours'),
('How can I contact customer care?', 'en', 'Approved fact sheet', 'Call customer care on +234 700 555 0199; our AI agent answers 24/7, and human agents are available Monday to Saturday, 7:00am to 9:00pm. WhatsApp Banking is +234 700 555 0188, open 24 hours every day. USSD is *347*88#. Email support@kindredmfb.example for general enquiries, complaints@kindredmfb.example for complaints and fraud@kindredmfb.example for fraud or card blocking.', 'Contact details', ARRAY['contact','phone number','call','customer care','email address','whatsapp','ussd','reach you'], 'general', 103, 'Bank profile, Contact and Hours'),
('What is your website and social media handle?', 'en', 'Approved fact sheet', 'Our website is www.kindredmfb.example. You can find us on Facebook, Instagram, X and LinkedIn as @KindredMFB.', 'Website and social', ARRAY['website','social media','facebook','instagram','linkedin','twitter','handle'], 'general', 104, 'Bank profile, Contact and Hours'),
('Where are your branches located?', 'en', 'Approved fact sheet', 'Our branches: Head Office, 27 Marina Crescent, Victoria Island, Lagos; Ikeja, 14 Obafemi Awolowo Way; Surulere, 9 Adeniran Ogunsanya Street; Wuse 2, Abuja, 31 Aminu Kano Crescent; GRA Port Harcourt, 18 Aba Road, GRA Phase 2; Ibadan, 5 Ring Road, Challenge; Benin City, 42 Sapele Road; Enugu, 11 Okpara Avenue, Independence Layout. Ikeja, Wuse 2, Port Harcourt and Benin City also open on Saturdays.', 'Branch locations', ARRAY['branch location','where is your branch','branches','address','nearest branch','head office'], 'general', 105, 'Bank profile, Contact and Hours'),
('Can I bank on a public holiday?', 'en', 'Approved fact sheet', 'Branches are closed on public holidays, but the Kindred app (iOS and Android), USSD, WhatsApp Banking, internet banking and Kindred Agents are available 24 hours, including public holidays.', 'Digital channels', ARRAY['public holiday','digital channels','app','internet banking','24 hours','weekend'], 'general', 106, 'Bank profile, Contact and Hours'),
('What savings accounts do you have?', 'en', 'Approved fact sheet', 'Everyday Savings opens with ₦1,000 and earns 4.0% a year, paid monthly, with no monthly fee and 4 free withdrawals a month, then ₦50 each. Goal Saver takes ₦5,000 a month and earns 6.0% a year, paid at maturity, locked for 3 to 12 months. Kids Saver opens with ₦500 and earns 5.0% a year, paid monthly. Would you like details on any of these?', 'Savings accounts', ARRAY['savings account','savings products','everyday savings','save money','interest on savings'], 'general', 110, 'Products (Savings)'),
('What happens if I leave Goal Saver early?', 'en', 'Approved fact sheet', 'Goal Saver is locked for 3 to 12 months. If you exit early, you forfeit 50% of the interest accrued so far.', 'Goal Saver early exit', ARRAY['goal saver','early exit','break goal saver','withdraw goal saver','locked savings'], 'general', 111, 'Products (Savings)'),
('Can I open an account for my child?', 'en', 'Approved fact sheet', 'Yes. Kids Saver is for under-18s and is opened and managed by a parent or guardian. It opens with ₦500 and earns 5.0% a year, paid monthly.', 'Kids Saver', ARRAY['kids saver','child account','children','my son','my daughter','under 18'], 'general', 112, 'Products (Savings)'),
('Do you have a current account?', 'en', 'Approved fact sheet', 'Yes. The Current Account opens with ₦10,000 and pays no interest. The ₦500 monthly fee is waived when your balance stays above ₦50,000, and a cheque book is available.', 'Current account', ARRAY['current account','cheque book','checkbook','business current'], 'general', 113, 'Products (Savings)'),
('What are your fixed deposit rates?', 'en', 'Approved fact sheet', 'Fixed Deposit starts from ₦100,000. Rates a year: 30 to 89 days, 8%; 90 to 179 days, 10%; 180 to 364 days, 11.5%; 365 days, 13%. Interest is paid at maturity, and early liquidation cuts the rate by 50%.', 'Fixed deposit rates', ARRAY['fixed deposit','fd rate','deposit rate','invest money'], 'general', 114, 'Products (Savings)'),
('When is interest paid on my savings?', 'en', 'Approved fact sheet', 'Everyday Savings and Kids Saver pay interest monthly. Goal Saver and Fixed Deposit pay interest at maturity.', 'Interest payment', ARRAY['when is interest paid','interest payment','interest paid monthly','maturity'], 'general', 115, 'Products (Savings)'),
('What loans do you offer?', 'en', 'Approved fact sheet', 'We offer Quick Salary Advance, the SME Growth Loan, Group (Cooperative) Loans, Asset Finance and Education Loans. Which one would you like to know more about?', 'Loan products', ARRAY['loans','loan products','borrow','types of loan'], 'general', 120, 'Products (Loan)'),
('What are the terms for the SME Growth Loan?', 'en', 'Approved fact sheet', 'The SME Growth Loan is ₦100,000 to ₦5,000,000 for 3 to 18 months at 3.0% a month on a reducing balance, with a 1.5% management fee. You need your business registration or a trade association letter, 6 months of statements and 1 guarantor.', 'SME Growth Loan', ARRAY['sme loan','business loan','sme growth','shop loan','trader loan'], 'general', 121, 'Products (Loan)'),
('How does asset finance work?', 'en', 'Approved fact sheet', 'Asset Finance is ₦200,000 to ₦3,000,000 for up to 12 months at 2.8% a month. You contribute 20% equity, and Kindred pays the supplier directly.', 'Asset Finance', ARRAY['asset finance','buy equipment','machine','generator','vehicle loan'], 'general', 122, 'Products (Loan)'),
('Can I get a loan for school fees?', 'en', 'Approved fact sheet', 'Yes. The Education Loan is ₦50,000 to ₦1,000,000 for up to 9 months at 2.0% a month. It is paid straight to the school, and you need an admission letter or fee invoice.', 'Education Loan', ARRAY['education loan','school fees','tuition','university','student loan'], 'general', 123, 'Products (Loan)'),
('What happens if I repay my loan late?', 'en', 'Approved fact sheet', 'Late repayment costs 1% of the overdue instalment per week, capped at 10%. Early settlement has no penalty, and interest is charged only up to the settlement date.', 'Late and early repayment', ARRAY['late repayment','repay late','early settlement','penalty','pay off loan'], 'general', 124, 'Products (Loan)'),
('How can I repay my loan?', 'en', 'Approved fact sheet', 'You can repay by auto-debit, in the app, by USSD, at a branch, through an agent, or by bank transfer to your loan repayment account number.', 'Repayment channels', ARRAY['how to repay','repayment channels','pay my loan','loan repayment'], 'general', 125, 'Products (Loan)'),
('How much does it cost to transfer to another bank?', 'en', 'Approved fact sheet', 'Transfers to Kindred accounts are free. Transfers to other banks cost ₦10 up to ₦5,000, ₦25 from ₦5,001 to ₦50,000 and ₦50 above ₦50,000. Account opening is free.', 'Transfer fees', ARRAY['transfer fee','transfer charge','other banks','interbank','send money cost'], 'general', 130, 'Fees, Cards & Tiers'),
('How do I get a debit card?', 'en', 'Approved fact sheet', 'A Verve debit card costs ₦1,000 and is delivered in 3 to 5 working days. A replacement card costs ₦1,500.', 'Debit card', ARRAY['debit card','verve','atm card','new card','card delivery','replacement card'], 'general', 131, 'Fees, Cards & Tiers'),
('How much are SMS alerts and statements?', 'en', 'Approved fact sheet', 'SMS alerts cost ₦4 each, and in-app notifications are free. E-statements are free; a printed statement costs ₦500 per 6 months. A reference or confirmation letter costs ₦2,000 and is ready in 2 working days.', 'Alerts and statements', ARRAY['sms alert','statement','e-statement','reference letter','confirmation letter'], 'general', 132, 'Fees, Cards & Tiers'),
('What are the account tiers and limits?', 'en', 'Approved fact sheet', 'Tier 1 needs your phone, name, date of birth, passport photo and BVN or NIN: ₦50,000 a day, ₦300,000 maximum balance. Tier 2 adds BVN, NIN and a valid ID: ₦200,000 a day, ₦500,000 maximum balance. Tier 3 adds proof of address and a utility bill: ₦1,000,000 a day, with no balance limit.', 'Account tiers', ARRAY['tier','account tier','transfer limit','daily limit','maximum balance','upgrade account'], 'general', 133, 'Fees, Cards & Tiers'),
('I forgot my app password.', 'en', 'Approved fact sheet', 'Tap "Forgot password" in the Kindred app and confirm with the OTP sent to your BVN-linked phone and a selfie. It resets in minutes. Never share your OTP with anyone.', 'Forgot password', ARRAY['forgot password','reset password','app password','locked out'], 'general', 140, 'Policies'),
('My account has not been used for a year. What happens?', 'en', 'Approved fact sheet', 'An account becomes dormant after 12 months with no customer transaction. You can reactivate it at any branch with a valid ID.', 'Dormant account', ARRAY['dormant','inactive account','reactivate','not used'], 'general', 141, 'Policies'),
('Do you sell or share my data?', 'en', 'Approved fact sheet', 'No. We handle your data under the Nigeria Data Protection Act, we do not sell customer data, and we never share one customer''s details with another person.', 'Data privacy', ARRAY['data privacy','my data','sell my data','share my information','privacy'], 'general', 142, 'Policies'),
('Do you have any promotions?', 'en', 'Approved fact sheet', 'Refer-a-Friend: you and your friend each get ₦1,000 when your friend deposits ₦5,000 within 30 days. Festive Goal Saver bonus: +1% interest until 31 December.', 'Promotions', ARRAY['promotion','refer a friend','referral','bonus','festive'], 'general', 143, 'Policies'),
('How do I make a complaint?', 'en', 'Approved fact sheet', 'You can email complaints@kindredmfb.example or tell us here. Complaints are acknowledged within 24 hours and resolved within 5 working days. If unresolved, they go to the Head of Customer Experience, then to the CBN consumer protection department.', 'Complaints process', ARRAY['make a complaint','complaint process','how long to resolve','escalate complaint'], 'general', 150, 'Complaints')
