ALTER TABLE public.voice_training_questions ADD COLUMN IF NOT EXISTS category text NOT NULL DEFAULT 'Policies'
  CHECK (category IN ('Products (Savings)','Products (Loan)','Bank profile, Contact and Hours','Fees, Cards & Tiers','Policies','Complaints'));

UPDATE public.voice_training_questions SET category = CASE topic
  WHEN 'Branch hours' THEN 'Bank profile, Contact and Hours'
  WHEN 'About Kindred Bank' THEN 'Bank profile, Contact and Hours'
  WHEN 'Account opening' THEN 'Policies'
  WHEN 'Account opening in Pidgin' THEN 'Policies'
  WHEN 'Fixed deposit example' THEN 'Products (Savings)'
  WHEN 'Quick Salary Advance' THEN 'Products (Loan)'
  WHEN 'Group Loan' THEN 'Products (Loan)'
  WHEN 'Loans in Yoruba' THEN 'Products (Loan)'
  WHEN 'ATM charges' THEN 'Fees, Cards & Tiers'
  WHEN 'Lost card' THEN 'Fees, Cards & Tiers'
  WHEN 'Failed transfer' THEN 'Complaints'
  WHEN 'Delayed reversal' THEN 'Complaints'
  ELSE 'Policies' END;

ON CONFLICT (question, language) DO NOTHING;